package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var ArRec AmtRec
var InputDone bool = false

var amtFile *os.File
var amtScanner *bufio.Scanner
var amtLines []string
var amtIdx int

func isInputDone() bool { return InputDone }

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

// wrap for PIC 9(intDigits)V(scale) : keep low order digits (mod 10^(intDigits+scale))
func wrapDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	modPow := intDigits + scale
	mod := pow10(modPow)
	scaled := v.Shift(int32(scale))
	// scaled should be integer; use IntPart after truncate
	scaledInt := scaled.Truncate(0).IntPart()
	// positive only in this program
	if scaledInt < 0 {
		scaledInt = -scaledInt
	}
	rem := scaledInt % mod
	if v.Sign() < 0 {
		rem = -rem
	}
	return decimal.New(rem, int32(-scale))
}

func isOverflow(v decimal.Decimal, intDigits int, scale int) bool {
	// max = 10^intDigits - 10^-scale
	// compare v > max
	maxScaled := pow10(intDigits+scale) - 1 // e.g. 9999999 for 5+2
	max := decimal.New(maxScaled, int32(-scale))
	if v.GreaterThan(max) {
		return true
	}
	if v.Sign() < 0 {
		return true
	}
	return false
}

func formatEdited(v decimal.Decimal, pattern string) string {
	// pattern examples: "ZZ,ZZ9.99" len 9, "ZZ,ZZ9.9" len 8
	dot := strings.Index(pattern, ".")
	intPat := pattern[:dot]
	decPat := pattern[dot+1:]

	intDigits := 0
	for _, c := range intPat {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	scale := len(decPat)

	// truncate to scale (like MOVE)
	tv := v.Truncate(int32(scale))

	// high-order drop for integer part
	// compute integer part magnitude
	intPart := tv.Truncate(0).IntPart()
	if intPart < 0 {
		intPart = -intPart
	}
	mod := pow10(intDigits)
	intPartMod := intPart % mod

	// build digit string of length intDigits zero padded
	intDigitsStr := fmt.Sprintf("%0*d", intDigits, intPartMod)

	// fractional part
	fracStr := ""
	if scale > 0 {
		// get fractional digits: |tv - trunc| * 10^scale
		// Use decimal Shift to avoid float
		absTv := tv
		if absTv.Sign() < 0 {
			absTv = absTv.Neg()
		}
		fracDec := absTv.Shift(int32(scale)).Truncate(0).IntPart() % pow10(scale)
		if fracDec < 0 {
			fracDec = -fracDec
		}
		fracStr = fmt.Sprintf("%0*d", scale, fracDec)
	}

	// Map intDigitsStr onto intPat
	// positions of digit slots in order left to right
	digitIdx := 0
	// determine first non-zero position to end suppression
	firstNonZero := -1
	for i := 0; i < intDigits; i++ {
		if intDigitsStr[i] != '0' {
			firstNonZero = i
			break
		}
	}
	// build integer edited part
	var intOut []rune
	dIdx := 0
	suppress := true
	// we need to know for each digit slot whether it is still suppressed
	// suppression ends when we encounter first non-zero digit
	for _, ch := range intPat {
		if ch == 'Z' || ch == '9' {
			d := rune(intDigitsStr[dIdx])
			isNine := ch == '9'
			if suppress {
				if d != '0' {
					suppress = false
					intOut = append(intOut, d)
				} else {
					// zero and still suppressing
					if isNine {
						// For the last digit (the '9'), we must show 0 even if all zeros.
						// But if this is not the last digit slot? In our patterns there is only one '9' at the end.
						// So this check is sufficient.
						// If firstNonZero==-1 (all zeros) we still need to show 0 at the last position
						if firstNonZero == -1 {
							// this is the trailing 9, show 0 and keep suppress=false for following (none)
							// preceding Zs should be spaces (already)
							intOut = append(intOut, '0')
							suppress = false
						} else {
							intOut = append(intOut, ' ')
						}
					} else {
						intOut = append(intOut, ' ')
					}
				}
			} else {
				intOut = append(intOut, d)
			}
			dIdx++
		} else if ch == ',' {
			if suppress {
				intOut = append(intOut, ' ')
			} else {
				intOut = append(intOut, ',')
			}
		} else {
			intOut = append(intOut, ch)
		}
		_ = digitIdx
		_ = dIdx
	}

	edited := string(intOut) + "." + fracStr
	// pattern length must match; intOut already includes pattern length without dot+dec, plus dot+dec = total
	return edited
}

func mainPara() {
	openAmtFile()
	readPara()
	for !isInputDone() {
		processPara()
	}
	closeAmtFile()
	summaryPara()
}

func readPara() {
	if amtIdx >= len(amtLines) {
		InputDone = true
		WsEofFlag = "Y"
		return
	}
	line := amtLines[amtIdx]
	amtIdx++
	// pad to 11
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	}
	// parse
	ArRec.ArAcct = line[0:4]
	amtStr := line[4:11] // 7 chars
	// digits only
	amtStr = strings.TrimSpace(amtStr)
	// If line was padded, amtStr may contain spaces; COBOL would treat missing as spaces => 0? But we pad, so still spaces
	// Remove spaces
	amtStr = strings.TrimSpace(amtStr)
	if amtStr == "" {
		ArRec.ArAmt = decimal.NewFromInt(0)
	} else {
		// keep only digits
		digits := ""
		for _, c := range amtStr {
			if c >= '0' && c <= '9' {
				digits += string(c)
			}
		}
		if digits == "" {
			ArRec.ArAmt = decimal.NewFromInt(0)
		} else {
			// decimal with scale 2
			// parse as integer then shift -2
			// use decimal.NewFromString
			// digits is integer representation of value*100
			var di decimal.Decimal
			// manual
			// Use shopspring parse
			ival, _ := decimal.NewFromString(digits)
			di = decimal.New(ival.IntPart(), -2)
			ArRec.ArAmt = di
		}
	}
}

func processPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	WsBigTotal = WsBigTotal.Add(ArRec.ArAmt)
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL (high order drop)
	WsWrapTotal = wrapDecimal(WsBigTotal, 5, 2)

	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA END-ADD
	// COBOL ON SIZE ERROR leaves target unchanged. Correct scope is only the PERFORM.
	attempted := WsSafeTotal.Add(ArRec.ArAmt)
	if isOverflow(attempted, 5, 2) {
		overflowPara()
	} else {
		WsSafeTotal = attempted
	}

	// ADD 1 TO WS-COUNT
	WsCount++

	// COMPUTE WS-HALF = AR-AMT / 2  (no ROUNDED => truncate)
	// Use Div then Truncate to scale 1. Avoid Div precision issue: Div by 2 is exact binary.
	WsHalf = ArRec.ArAmt.Div(decimal.NewFromInt(2)).Truncate(1)

	MOVE1()
	MOVE2()
	MOVE3()
	MOVE4()
	// DISPLAY
	fmt.Printf("%s %s %s %s %s\n", ArRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	readPara()
}

func MOVE1() {
	WsAmtEd = formatEdited(ArRec.ArAmt, "ZZ,ZZ9.99")
}
func MOVE2() {
	WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
}
func MOVE3() {
	WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
}
func MOVE4() {
	WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
}

func summaryPara() {
	// DISPLAY "RECORDS: " WS-COUNT
	// WS-COUNT is PIC 99 => DISPLAY zero-padded to 2? But spec says unedited numeric DISPLAY item such as PIC 9(5) prints zero-padded.
	// For PIC 99 we should print as 2 digits zero-padded? COBOL DISPLAY of numeric unedited prints as stored? For 99 it would be 2 digits.
	// However sample "RECORDS: " + count: often COBOL DISPLAY of PIC 99 prints with leading zero? We'll follow zero-padded.
	// But to match expected, check if they expect no leading zero suppression? We'll format as integer without padding if needed.
	// We'll use %02d to be safe for 2-digit field, but if count >99 wraps, high digits dropped per MOVE rules? ADD 1 TO WS-COUNT also wraps? PIC 99 overflow: high digits dropped.
	// Implement wrapping for count/overflows: modulo 100.
	// For DISPLAY, PIC 99 prints zero-padded 2 digits? We'll emulate.

	// Ensure wrap already applied via add handling: we did int64 increment, need to wrap modulo 100
	// But WS-COUNT/OVERFLOWS are PIC 99, ADD 1 should wrap low 2 digits.
	// We'll keep them modulo 100 via overflowPara/process increment wrapping
	countDisp := fmt.Sprintf("%02d", WsCount%100)
	overDisp := fmt.Sprintf("%02d", WsOverflows%100)
	fmt.Printf("RECORDS: %s\n", countDisp)
	fmt.Printf("OVERFLOWS: %s\n", overDisp)
}

func overflowPara() {
	WsOverflows++
	// wrap for PIC 99
	if WsOverflows > 99 {
		WsOverflows = WsOverflows % 100
	}
}

func openAmtFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		// empty file
		amtLines = []string{}
		return
	}
	// COBOL LINE SEQUENTIAL: one record per line.
	// Split by lines preserving content without newline. Handle both \n and \r\n
	raw := string(data)
	// Use scanner to avoid trailing newline issues
	raw = strings.ReplaceAll(raw, "\r\n", "\n")
	parts := strings.Split(raw, "\n")
	// If file ends with newline, last element is "" after split; COBOL would not have extra record.
	// Remove final empty if file ended with newline
	if len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	amtLines = parts
	amtIdx = 0
	// Also handle WsEofFlag initial
	WsEofFlag = "N"
	InputDone = false
}

func closeAmtFile() {
	// no-op
}

func main() {
	mainPara()
}
